class Listener:
    def update(self, value):
        pass

class Printer(Listener):
    def update(self, value):
        print(f"Got: {value}")

class Doubler(Listener):
    def update(self, value):
        print(f"Doubled: {value * 2}")

class Source:
    def __init__(self):
        self.listeners = []

    def add(self, listener):
        self.listeners.append(listener)

    def fire(self, value):
        for l in self.listeners:
            l.update(value)

source = Source()
source.add(Printer())
source.add(Doubler())
source.fire(5)
```

